package com.acme.shortener.analytics;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.acme.shortener.TestcontainersConfiguration;
import com.acme.shortener.url.HostResolver;
import java.net.InetAddress;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Import;
import org.springframework.context.annotation.Primary;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import tools.jackson.databind.json.JsonMapper;

/** GET /api/v1/links/{code}/stats.csv over real Postgres. */
@SpringBootTest
@AutoConfigureMockMvc
@Import({TestcontainersConfiguration.class, StatsCsvIT.PublicDns.class})
class StatsCsvIT {

  private static final String KEY = "test-key"; // owner "tester"
  private static final String OTHER_KEY = "other-key";

  @Autowired MockMvc mvc;
  @Autowired JsonMapper json;
  @Autowired JdbcTemplate jdbc;

  @TestConfiguration
  static class PublicDns {
    @Bean
    @Primary
    HostResolver fakeHostResolver() throws Exception {
      InetAddress ip = InetAddress.getByName("93.184.215.14");
      return host -> List.of(ip);
    }
  }

  @Test
  void dailyClicksAsCsvZeroFilled() throws Exception {
    String code = create();
    jdbc.update(
        "INSERT INTO click_daily (link_id, day, clicks)"
            + " SELECT id, DATE '2026-03-02', 2 FROM link WHERE code = ?",
        code);

    mvc.perform(
            get("/api/v1/links/" + code + "/stats.csv?from=2026-03-01&to=2026-03-03")
                .header("X-API-Key", KEY))
        .andExpect(status().isOk())
        .andExpect(content().contentTypeCompatibleWith("text/csv"))
        .andExpect(
            header()
                .string("Content-Disposition", "attachment; filename=\"" + code + "-clicks.csv\""))
        .andExpect(content().string("day,clicks\n2026-03-01,0\n2026-03-02,2\n2026-03-03,0\n"));
  }

  @Test
  void theRangeRulesAndOwnerCheckAreThoseOfTheJsonStats() throws Exception {
    String code = create();

    mvc.perform(get("/api/v1/links/" + code + "/stats.csv").header("X-API-Key", KEY))
        .andExpect(status().isOk())
        .andExpect(
            content().string(org.hamcrest.Matchers.startsWith("day,clicks\n"))); // last 30 days
    mvc.perform(
            get("/api/v1/links/" + code + "/stats.csv?from=2026-03-05&to=2026-03-01")
                .header("X-API-Key", KEY))
        .andExpect(status().isBadRequest())
        .andExpect(jsonPath("$.type").value("/problems/invalid-stats-range"));
    mvc.perform(get("/api/v1/links/" + code + "/stats.csv").header("X-API-Key", OTHER_KEY))
        .andExpect(status().isNotFound())
        .andExpect(jsonPath("$.type").value("/problems/link-not-found"));
    mvc.perform(get("/api/v1/links/" + code + "/stats.csv")).andExpect(status().isUnauthorized());
  }

  private String create() throws Exception {
    String response =
        mvc.perform(
                post("/api/v1/links")
                    .header("X-API-Key", KEY)
                    .contentType(MediaType.APPLICATION_JSON)
                    .content("{\"url\":\"https://example.com/csv\"}"))
            .andExpect(status().isCreated())
            .andReturn()
            .getResponse()
            .getContentAsString();
    return (String) json.readValue(response, Map.class).get("code");
  }
}

package com.acme.shortener.analytics;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class StatsCsvTest {

  private static final LocalDate D1 = LocalDate.parse("2026-03-01");

  @Test
  void oneRowPerDayOldestFirstAfterTheHeader() {
    LinkStats stats =
        new LinkStats(
            "csv0001",
            D1,
            D1.plusDays(2),
            2,
            1,
            List.of(
                new LinkStats.DayClicks(D1, 0),
                new LinkStats.DayClicks(D1.plusDays(1), 2),
                new LinkStats.DayClicks(D1.plusDays(2), 0)),
            List.of(),
            Map.of());

    assertThat(StatsCsv.dailyClicks(stats))
        .isEqualTo("day,clicks\n2026-03-01,0\n2026-03-02,2\n2026-03-03,0\n");
  }

  @Test
  void noDaysIsJustTheHeader() {
    LinkStats stats = new LinkStats("csv0002", D1, D1, 0, 0, List.of(), List.of(), Map.of());

    assertThat(StatsCsv.dailyClicks(stats)).isEqualTo(StatsCsv.HEADER + "\n");
  }
}

package com.acme.shortener.link;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.acme.shortener.TestcontainersConfiguration;
import com.acme.shortener.url.HostResolver;
import java.net.InetAddress;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Import;
import org.springframework.context.annotation.Primary;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import tools.jackson.databind.json.JsonMapper;

/** The optional note on a link, over real Postgres. */
@SpringBootTest
@AutoConfigureMockMvc
@Import({TestcontainersConfiguration.class, LinkNoteIT.PublicDns.class})
class LinkNoteIT {

  private static final String KEY = "test-key"; // owner "tester"

  @Autowired MockMvc mvc;
  @Autowired JsonMapper json;

  @TestConfiguration
  static class PublicDns {
    @Bean
    @Primary
    HostResolver fakeHostResolver() throws Exception {
      InetAddress ip = InetAddress.getByName("93.184.215.14");
      return host -> List.of(ip);
    }
  }

  @Test
  void aNoteIsStoredAndReturnedOnCreateAndGet() throws Exception {
    String code =
        create("{\"url\":\"https://example.com/n1\",\"note\":\"spring campaign\"}", "note-1");

    mvc.perform(get("/api/v1/links/" + code).header("X-API-Key", KEY))
        .andExpect(status().isOk())
        .andExpect(jsonPath("$.note").value("spring campaign"));
  }

  @Test
  void aCustomAliasKeepsItsNoteToo() throws Exception {
    String code =
        create(
            "{\"url\":\"https://example.com/n2\",\"customAlias\":\"note-alias\",\"note\":\"flyer\"}",
            "note-2");

    assertThat(code).isEqualTo("note-alias");
    mvc.perform(get("/api/v1/links/note-alias").header("X-API-Key", KEY))
        .andExpect(jsonPath("$.note").value("flyer"));
  }

  @Test
  void withoutANoteItIsNull() throws Exception {
    String code = create("{\"url\":\"https://example.com/n3\"}", "note-3");

    mvc.perform(get("/api/v1/links/" + code).header("X-API-Key", KEY))
        .andExpect(status().isOk())
        .andExpect(jsonPath("$.note").doesNotExist());
  }

  @Test
  void aNoteLongerThan280CharactersIsRejected() throws Exception {
    mvc.perform(
            post("/api/v1/links")
                .header("X-API-Key", KEY)
                .contentType(MediaType.APPLICATION_JSON)
                .content(
                    "{\"url\":\"https://example.com/n4\",\"note\":\"" + "x".repeat(281) + "\"}"))
        .andExpect(status().isBadRequest())
        .andExpect(jsonPath("$.type").value("/problems/validation-failed"));
    create("{\"url\":\"https://example.com/n5\",\"note\":\"" + "x".repeat(280) + "\"}", "note-5");
  }

  @Test
  void theRedirectNeverShowsTheNote() throws Exception {
    String code =
        create("{\"url\":\"https://example.com/n6\",\"note\":\"private reminder\"}", "note-6");

    String body =
        mvc.perform(get("/" + code))
            .andExpect(status().isFound())
            .andExpect(header().string("Location", "https://example.com/n6"))
            .andReturn()
            .getResponse()
            .getContentAsString();
    assertThat(body).doesNotContain("private reminder");
  }

  /** Creates a link and checks the create response carries the same note as the request. */
  private String create(String body, String idempotencyKey) throws Exception {
    String response =
        mvc.perform(
                post("/api/v1/links")
                    .header("X-API-Key", KEY)
                    .header("Idempotency-Key", idempotencyKey)
                    .contentType(MediaType.APPLICATION_JSON)
                    .content(body))
            .andExpect(status().isCreated())
            .andReturn()
            .getResponse()
            .getContentAsString();
    Map<?, ?> request = json.readValue(body, Map.class);
    Map<?, ?> created = json.readValue(response, Map.class);
    assertThat(created.get("note")).isEqualTo(request.get("note"));
    return (String) created.get("code");
  }
}
